<?php
declare(strict_types=1);header('Content-Type:text/html;charset=UTF-8');header('Cache-Control:no-transform,no-store,private');require dirname(__DIR__,2).'/bootstrap.php';require_once __DIR__.'/automatic-common-setup.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\AutomaticJudgeBrowserService;use App\Services\SpecialCategoryService;Auth::requireAdmin();$pdo=Database::connection();$userId=(int)(Auth::user()['id']??0);$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$error=(string)($_SESSION['automatic_scoring_error']??'');$notice=(string)($_SESSION['automatic_scoring_notice']??'');unset($_SESSION['automatic_scoring_error'],$_SESSION['automatic_scoring_notice']);$s=$pdo->prepare("SELECT r.*,e.name event_name,e.event_date FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id AND r.scoring_mode='automated'");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Automatic scoring round not found.');}if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::verify($_POST['_csrf']??null)&&($_POST['action']??'')==='unlock_judge'){$judgeId=(int)($_POST['judge_id']??0);$reason=trim((string)($_POST['reason']??''));try{if($round['status']==='completed')throw new RuntimeException('Completed round is locked. Use the Scorer, Master Scorer or Super Admin RESUBMIT override first.');AutomaticJudgeBrowserService::unlock($pdo,$roundId,$judgeId,$userId,$reason);$pdo->prepare("UPDATE bdc_scoring_rounds SET status=CASE WHEN status='scores_submitted' THEN 'draft' ELSE status END WHERE id=:r")->execute(['r'=>$roundId]);$notice='Judge submission reopened. Existing marks remain available for correction and resubmission.';}catch(Throwable $e){$error=$e->getMessage();}}$category=SpecialCategoryService::isSpecial((string)$round['division'])?SpecialCategoryService::label((string)$round['division']):ucwords(str_replace('_',' ',(string)$round['division']));$setup=$round['round_type']==='final'?'':bdcRenderAutomaticCommonSetup($roundId);AutomaticJudgeBrowserService::syncRound($pdo,$roundId);$progress=AutomaticJudgeBrowserService::progress($pdo,$roundId);$allJudgesSubmitted=!empty($progress)&&count(array_filter($progress,fn($row)=>(string)($row['session_status']??'')==='submitted'))===count($progress);$scoresCompleted=in_array((string)$round['status'],['awaiting_decision','scores_submitted','tie_pending','completed'],true);$tieStmt=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_results WHERE round_id=:r AND result_status='tie_pending'");$tieStmt->execute(['r'=>$roundId]);$hasCallbackTies=(int)$tieStmt->fetchColumn()>0;$tieCandidates=[];if($hasCallbackTies){$tieCandidatesStmt=$pdo->prepare("SELECT sr.entry_id,se.display_name,se.dance_role,sr.rank_number,sr.total_score,sr.chief_score FROM bdc_scoring_results sr JOIN bdc_scoring_entries se ON se.id=sr.entry_id WHERE sr.round_id=:r AND sr.result_status='tie_pending' ORDER BY se.dance_role,sr.rank_number,se.display_name");$tieCandidatesStmt->execute(['r'=>$roundId]);$tieCandidates=$tieCandidatesStmt->fetchAll();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Automatic Scoring | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.matrix th{white-space:nowrap;position:sticky;top:0;background:#fff}.provisional{background:#fff3cd}.score-high{font-weight:800}.status-submitted{color:#198754}.status-scoring{color:#0d6efd}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><div><a class="btn btn-outline-light btn-sm" href="./?mode=automated">All Rounds</a> <a class="btn btn-danger btn-sm" href="../live-screen/control.php?round_id=<?=$roundId?>">Live Screen</a></div></div></nav><main class="container-fluid py-4" style="max-width:1800px"><div class="d-flex justify-content-between"><div><div class="text-primary fw-bold">AUTOMATIC SCORING</div><h1 class="h3"><?=e($round['event_name'])?></h1><div class="text-muted"><?=e(!empty($round['scheduled_at'])?date('d M Y, g:i A',strtotime((string)$round['scheduled_at'])):($round['event_date']?date('d M Y',strtotime((string)$round['event_date'])).' · Time pending':'Date & time pending'))?> · <?=e($category)?> · <?=e(ucfirst($round['round_type']))?></div></div><span class="badge <?=$scoresCompleted?'text-bg-success':'text-bg-warning'?> align-self-start"><?=$scoresCompleted?'SCORING COMPLETED':'LIVE / PROVISIONAL'?></span></div><?php if($round['status']==='completed'):?><div class="alert alert-warning mt-3"><strong>Completed round locked.</strong> Scores remain visible and cannot be changed until an authorised resubmission override is confirmed.<?php if(Auth::canOverrideCompletedScores()):?><form method="post" action="index.php?mode=automated&amp;round_id=<?=$roundId?>" class="d-flex gap-2 flex-wrap mt-2 completed-round-reopen" onsubmit="return confirm('Unlock this completed automatic round for correction and resubmission? Existing child rounds will be preserved.');"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="reopen_completed_round"><input type="hidden" name="round_id" value="<?=$roundId?>"><input class="form-control form-control-sm" style="max-width:180px" name="resubmit_confirmation" placeholder="Type RESUBMIT" required><button class="btn btn-sm btn-warning">Unlock for Resubmission</button></form><?php else:?><div class="small mt-2">A Scorer, Master Scorer or Super Admin must unlock this round.</div><?php endif;?></div><script>addEventListener('DOMContentLoaded',()=>document.querySelectorAll('form:not(.completed-round-reopen)').forEach(form=>form.querySelectorAll('button,input:not([type=hidden]),select,textarea').forEach(control=>control.disabled=true)));</script><?php endif;?><?php if($error):?><div class="alert alert-danger mt-3"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success mt-3"><?=e($notice)?></div><?php endif;?><?=$setup?><div class="card shadow-sm mt-4 <?=$scoresCompleted?'border-success':'border-primary'?>" id="automaticRoundWorkflow"><div class="card-body"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap mb-3"><div><strong><?=$scoresCompleted?'✓ Scoring Completed':'Round Score Completion'?></strong><div class="small <?=$scoresCompleted?'text-success':'text-muted'?>"><?=$scoresCompleted?'Scores are submitted and callback results are ready.':'Save, calculate, review and submit without leaving Automatic Scoring.'?></div></div><a class="btn btn-outline-primary" target="_blank" href="result.php?round_id=<?=$roundId?>">Preview / Print Scores</a></div><div class="d-flex flex-wrap gap-2"><form method="post" action="index.php?mode=automated&amp;round_id=<?=$roundId?>"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="action" value="save_scores"><button class="btn btn-outline-dark">Save Scores Draft</button></form><form method="post" action="index.php?mode=automated&amp;round_id=<?=$roundId?>"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="action" value="calculate_scores"><button class="btn btn-warning" <?=$allJudgesSubmitted?'':'disabled'?>>Calculate &amp; Sort</button></form><form method="post" action="index.php?mode=automated&amp;round_id=<?=$roundId?>" onsubmit="return confirm('Submit scores and calculate the callback result?')"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="action" value="submit_scores"><button id="automaticSubmitScores" class="btn <?=$allJudgesSubmitted?'btn-success':'btn-primary'?>" <?=$allJudgesSubmitted?'':'disabled'?>><?=$allJudgesSubmitted?'Submit Scores':'Waiting for All Judges'?></button></form></div><?php if($scoresCompleted && $round['status']!=='completed'):?><div class="border-top mt-3 pt-3"><strong>Callback / Next Round</strong><?php if($hasCallbackTies):?><?php
$tiePanelTest=false;
$tiePanelAction='index.php?mode=automated&round_id='.$roundId;
$tiePanelAttributes="";
require dirname(__DIR__).'/scoring/tie-resolution-panel.php';
?><?php else:?><div class="d-flex flex-wrap gap-2 mt-2"><?php if($round['round_type']==='heats'):?><form method="post" action="index.php?mode=automated&amp;round_id=<?=$roundId?>"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="create_next_round"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="next_round_type" value="semifinal"><div class="border rounded p-2 mb-2" style="min-width:340px"><div class="small fw-bold mb-2">Next-round schedule</div><div class="row g-2"><div class="col-12"><label class="form-label small mb-1">Date</label><input class="form-control form-control-sm" type="date" name="next_schedule_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="col-4"><label class="form-label small mb-1">Hour</label><select class="form-select form-select-sm" name="next_schedule_hour" required><?php for($scheduleHour=1;$scheduleHour<=12;$scheduleHour++):?><option value="<?=$scheduleHour?>"><?=$scheduleHour?></option><?php endfor;?></select></div><div class="col-4"><label class="form-label small mb-1">Minute</label><select class="form-select form-select-sm" name="next_schedule_minute" required><?php for($scheduleMinute=0;$scheduleMinute<60;$scheduleMinute+=5):$scheduleMinuteLabel=str_pad((string)$scheduleMinute,2,'0',STR_PAD_LEFT);?><option value="<?=$scheduleMinute?>"><?=$scheduleMinuteLabel?></option><?php endfor;?></select></div><div class="col-4"><label class="form-label small mb-1">AM / PM</label><select class="form-select form-select-sm" name="next_schedule_period" required><option value="AM">AM</option><option value="PM">PM</option></select></div></div></div><button class="btn btn-warning">Move Callbacks to Semifinal</button></form><form method="post" action="index.php?mode=automated&amp;round_id=<?=$roundId?>"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="create_next_round"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="next_round_type" value="final"><div class="border rounded p-2 mb-2" style="min-width:340px"><div class="small fw-bold mb-2">Next-round schedule</div><div class="row g-2"><div class="col-12"><label class="form-label small mb-1">Date</label><input class="form-control form-control-sm" type="date" name="next_schedule_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="col-4"><label class="form-label small mb-1">Hour</label><select class="form-select form-select-sm" name="next_schedule_hour" required><?php for($scheduleHour=1;$scheduleHour<=12;$scheduleHour++):?><option value="<?=$scheduleHour?>"><?=$scheduleHour?></option><?php endfor;?></select></div><div class="col-4"><label class="form-label small mb-1">Minute</label><select class="form-select form-select-sm" name="next_schedule_minute" required><?php for($scheduleMinute=0;$scheduleMinute<60;$scheduleMinute+=5):$scheduleMinuteLabel=str_pad((string)$scheduleMinute,2,'0',STR_PAD_LEFT);?><option value="<?=$scheduleMinute?>"><?=$scheduleMinuteLabel?></option><?php endfor;?></select></div><div class="col-4"><label class="form-label small mb-1">AM / PM</label><select class="form-select form-select-sm" name="next_schedule_period" required><option value="AM">AM</option><option value="PM">PM</option></select></div></div></div><button class="btn btn-dark">Move Callbacks Directly to Final</button></form><?php elseif($round['round_type']==='semifinal'):?><form method="post" action="index.php?mode=automated&amp;round_id=<?=$roundId?>"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="create_next_round"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="next_round_type" value="final"><div class="border rounded p-2 mb-2" style="min-width:340px"><div class="small fw-bold mb-2">Next-round schedule</div><div class="row g-2"><div class="col-12"><label class="form-label small mb-1">Date</label><input class="form-control form-control-sm" type="date" name="next_schedule_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="col-4"><label class="form-label small mb-1">Hour</label><select class="form-select form-select-sm" name="next_schedule_hour" required><?php for($scheduleHour=1;$scheduleHour<=12;$scheduleHour++):?><option value="<?=$scheduleHour?>"><?=$scheduleHour?></option><?php endfor;?></select></div><div class="col-4"><label class="form-label small mb-1">Minute</label><select class="form-select form-select-sm" name="next_schedule_minute" required><?php for($scheduleMinute=0;$scheduleMinute<60;$scheduleMinute+=5):$scheduleMinuteLabel=str_pad((string)$scheduleMinute,2,'0',STR_PAD_LEFT);?><option value="<?=$scheduleMinute?>"><?=$scheduleMinuteLabel?></option><?php endfor;?></select></div><div class="col-4"><label class="form-label small mb-1">AM / PM</label><select class="form-select form-select-sm" name="next_schedule_period" required><option value="AM">AM</option><option value="PM">PM</option></select></div></div></div><button class="btn btn-dark">Move Semifinal Callbacks to Final</button></form><?php endif;?></div><?php endif;?></div><?php endif;?></div></div><div class="card shadow-sm mt-4"><div class="card-header d-flex justify-content-between align-items-center"><strong>Judge Progress</strong><span class="small text-muted">Auto refresh every 1.5 seconds</span></div><div class="card-body" id="judgeProgress">Loading…</div></div><div class="card shadow-sm mt-4"><div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-2"><div><strong>Competitor Scoring Matrix</strong><div class="small text-muted">Current scores are provisional until the round is calculated.</div></div><div class="d-flex gap-2"><select id="sortMode" class="form-select form-select-sm"><option value="score_desc">Score High → Low</option><option value="score_asc">Score Low → High</option><option value="bib">Bib Number</option><option value="name">Name</option><option value="original">Original Order</option></select><label class="btn btn-outline-secondary btn-sm"><input id="autoSort" type="checkbox" checked> Auto Sort</label></div></div><div class="card-body p-0"><div class="table-responsive" style="max-height:70vh"><table class="table table-bordered table-hover align-middle matrix mb-0"><thead id="matrixHead"></thead><tbody id="matrixBody"><tr><td>Loading…</td></tr></tbody></table></div></div></div></main><script>const rid=<?=$roundId?>,csrf=<?=json_encode(Csrf::token())?>;let data=null,original=[];const jp=document.getElementById('judgeProgress'),head=document.getElementById('matrixHead'),body=document.getElementById('matrixBody'),sort=document.getElementById('sortMode'),auto=document.getElementById('autoSort');function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function renderJudges(){jp.innerHTML=data.judges.map(j=>`<div class="border rounded p-2 mb-2 d-flex flex-wrap justify-content-between gap-2"><div><strong>${esc(j.judge_name)}${Number(j.is_chief)?' ★':''}</strong> <span class="badge text-bg-secondary">${esc(String(j.scoring_scope).toUpperCase())}</span></div><div><strong class="status-${esc(j.session_status)}">${esc(String(j.session_status).replaceAll('_',' ').toUpperCase())}</strong> · ${j.done}/${j.total} · ${j.percent}% ${j.session_status==='submitted'?`<button class="btn btn-sm btn-outline-warning ms-2" onclick="unlockJudge(${j.judge_id},'${esc(j.judge_name)}')">Reopen</button>`:''}</div></div>`).join('')}function sortedRows(){let rows=[...data.entries];if(!auto.checked&&sort.value==='original')return original.map(i=>rows.find(x=>(x.id??x.pair_id)===i)).filter(Boolean);switch(sort.value){case'score_asc':rows.sort((a,b)=>(a.score??999999)-(b.score??999999));break;case'bib':rows.sort((a,b)=>(a.bib_number??a.pair_number)-(b.bib_number??b.pair_number));break;case'name':rows.sort((a,b)=>String(a.display_name??a.leader_name).localeCompare(String(b.display_name??b.leader_name)));break;case'original':break;default:if(data.round_type!=='final')rows.sort((a,b)=>(b.score??0)-(a.score??0));}return rows}function renderMatrix(){const js=data.judge_columns;head.innerHTML='<tr><th>Provisional</th><th>Competitor / Couple</th>'+js.map(j=>`<th>J${j.judge_order}${Number(j.is_chief)?'★':''}<br><small>${esc(j.judge_name)}</small></th>`).join('')+(data.round_type==='final'?'':'<th>Current Score</th>')+'</tr>';body.innerHTML=sortedRows().map((x,i)=>`<tr><td class="provisional">${data.round_type==='final'?'—':i+1}</td><td><strong>${data.round_type==='final'?'Couple '+x.pair_number:'#'+x.bib_number+' '+esc(x.display_name)}</strong>${data.round_type==='final'?'<br>'+esc(x.leader_name)+' & '+esc(x.follower_name):'<br><small>'+esc(x.dance_role)+'</small>'}</td>${js.map(j=>`<td>${esc(x.marks[j.id]??'—')}</td>`).join('')}${data.round_type==='final'?'':`<td class="score-high">${Number(x.score).toFixed(1)}</td>`}</tr>`).join('')}async function refresh(){try{const r=await fetch('automatic-live-data.php?round_id='+rid+'&_='+Date.now(),{cache:'no-store'}),j=await r.json();if(!j.ok)return;if(!data)original=j.entries.map(x=>x.id??x.pair_id);data=j;renderJudges();renderMatrix()}catch(e){console.error(e)}}function unlockJudge(id,name){const reason=prompt('Reason for reopening '+name+' submission:');if(!reason)return;const f=document.createElement('form');f.method='post';f.innerHTML=`<input type="hidden" name="_csrf" value="${esc(csrf)}"><input type="hidden" name="action" value="unlock_judge"><input type="hidden" name="judge_id" value="${id}"><input type="hidden" name="reason" value="${esc(reason)}">`;document.body.appendChild(f);f.submit()}sort.addEventListener('change',()=>data&&renderMatrix());auto.addEventListener('change',()=>data&&renderMatrix());refresh();setInterval(()=>{if(!document.hidden)refresh()},5000);</script><script>(function(){const sourceBody=document.getElementById('matrixBody'),sourceHead=document.getElementById('matrixHead'),sourceWrap=sourceBody?.closest('.table-responsive');if(!sourceBody||!sourceHead||!sourceWrap)return;const style=document.createElement('style');style.textContent='.live-split-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;padding:12px}.live-role-pane{min-width:0;border:1px solid #ced4da;border-radius:8px;overflow:hidden;background:#fff}.live-role-title{padding:9px 12px;font-weight:800}.live-role-scroll{overflow:auto;max-height:62vh;scrollbar-gutter:stable}.live-role-scroll table{width:max-content;min-width:100%;margin:0}.live-role-scroll th,.live-role-scroll td{min-width:58px;white-space:nowrap}.live-role-scroll th:first-child,.live-role-scroll td:first-child{position:sticky;left:0;z-index:3;background:#fff;min-width:72px}.live-role-scroll th:nth-child(2),.live-role-scroll td:nth-child(2){position:sticky;left:72px;z-index:3;background:#fff;min-width:190px;white-space:normal}.live-role-scroll thead th{position:sticky;top:0;z-index:4;background:#f8f9fa}@media(max-width:1100px){.live-split-grid{grid-template-columns:1fr}}';document.head.appendChild(style);const host=document.createElement('div');host.className='live-split-grid';host.innerHTML='<section class="live-role-pane"><div class="live-role-title bg-primary-subtle">LEADERS</div><div class="live-role-scroll"><table class="table table-bordered table-sm"><thead data-role-head="leader"></thead><tbody data-role-body="leader"></tbody></table></div></section><section class="live-role-pane"><div class="live-role-title bg-danger-subtle">FOLLOWERS</div><div class="live-role-scroll"><table class="table table-bordered table-sm"><thead data-role-head="follower"></thead><tbody data-role-body="follower"></tbody></table></div></section>';sourceWrap.after(host);sourceWrap.style.display='none';function paintSplit(){const rows=[...sourceBody.querySelectorAll('tr')],roleRows=rows.filter(row=>/^(leader|follower)$/.test(row.querySelector('td:nth-child(2) small')?.textContent.trim().toLowerCase()||''));if(!roleRows.length){sourceWrap.style.display='block';host.style.display='none';return}sourceWrap.style.display='none';host.style.display='grid';['leader','follower'].forEach(role=>{host.querySelector('[data-role-head="'+role+'"]').innerHTML=sourceHead.innerHTML;const target=host.querySelector('[data-role-body="'+role+'"]');target.innerHTML='';roleRows.filter(row=>(row.querySelector('td:nth-child(2) small')?.textContent.trim().toLowerCase()||'')===role).forEach((row,index)=>{const clone=row.cloneNode(true),rank=clone.querySelector('td:first-child');if(rank)rank.textContent=String(index+1);target.appendChild(clone)})})}new MutationObserver(paintSplit).observe(sourceBody,{childList:true});paintSplit()})();</script><script>(function(){function sync(){const button=document.getElementById('automaticSubmitScores');if(!button||!data?.judges?.length)return;const ready=data.judges.every(j=>j.session_status==='submitted'),label=ready?'Submit Scores':'Waiting for All Judges';button.disabled=!ready;button.classList.toggle('btn-success',ready);button.classList.toggle('btn-primary',!ready);if(button.textContent!==label)button.textContent=label}setInterval(sync,750);sync()})();</script></body></html>
